count": 0, "open_access": {"is_oa": true, "oa_status": "green", "oa_url": "https://arxiv.org/pdf/2603.25031", "any_repository_has_fulltext": true}, "primary_location": {"id": "pmh:oai:arXiv.org:2603.25031", "doi": null, "is_oa": true, "landing_page_url": "https://arxiv.org/abs/2603.25031", "pdf_url": "https://arxiv.org/pdf/2603.25031", "source": {"id": "https://openalex.org/S4306400194", "display_name": "arXiv (Cornell University)", "issn_l": "2331-8422", "issn": ["2331-8422"], "is_oa": true, "is_in_doaj": false, "is_core": false, "listed_in": [], "host_organization": "https://openalex.org/I205783295", "host_organization_name": "Cornell University", "host_organization_lineage": ["https://openalex.org/I205783295"], "host_organization_lineage_names": [], "type": "repository"}, "license": "cc-by-nc-nd", "license_id": "https://openalex.org/licenses/cc-by-nc-nd", "version": "submittedVersion", "is_accepted": false, "is_published": false, "raw_source_name": null, "raw_type": "text"}, "abstract": "In psychological support and emotional companionship scenarios, the core limitation of large language models (LLMs) lies not merely in response quality, but in their reliance on local next-token prediction, which prevents them from maintaining the temporal continuity, stage awareness, and user consent boundaries required for multi-turn intervention. This stateless characteristic makes systems prone to premature advancement, stage misalignment, and boundary violations in continuous dialogue. To address this problem, we argue that the key challenge in process-oriented emotional support is not simply generating natural language, but constructing a sustainably updatable external situational structure for the model. We therefore propose LEKIA 2.0, a situated LLM architecture that separates the cognitive layer from the executive layer, thereby decoupling situational modeling from intervention execution. This design enables the system to maintain stable representations of the user's situation and consent boundaries throughout ongoing interaction. To evaluate this process-control capability, we further introduce a Static-to-Dynamic online evaluation protocol for multi-turn interaction. LEKIA achieved an average absolute improvement of approximately 31% over prompt-only baselines in deep intervention loop completion. The results suggest that an external situational structure is a key enabling condition for building stable, controllable, and situated emotional support systems."}]", "excerpt_truncated": true, "source_sha256": "cb38dfd684b403a174e2f8fbd4de1882e9dac906b2c674897a5c8fe09f722527", "verification_required": true, "topic_domain": "assumption_challenge", "evidence_role": "discovery", "host_tier": "discovery", "source_identity": null, "persistent_identifiers": ["doi:10.5281/zenodo.18989117", "openalex:W7135031104", "arxiv:2603.25031"], "source_candidates": ["https://doi.org/10.5281/zenodo.18989117", "https://arxiv.org/pdf/2603.25031", "https://arxiv.org/abs/2603.25031"], "source_candidate_identities": {}}
